// Generated by AI (UnitTest MCP)
import { describe, expect, it } from "vitest";

import { auditDesigns, isDrift } from "../../../scripts/design-audit.mjs";

const adr = (number, status, slug = "thing") => ({
  number,
  file: `${number}-${slug}.md`,
  path: `docs/adr/${number}-${slug}.md`,
  title: "A decision",
  status,
});

const row = (number, status, decided_by, slug = "thing") => ({
  id: `design:${number}-${slug}`,
  adr_path: `docs/adr/${number}-${slug}.md`,
  title: `ADR-${number}`,
  status,
  decided_by,
});

const kinds = (findings) => findings.map((f) => f.kind);

describe("auditDesigns", () => {
  it("reports nothing when every file has a matching decided row", () => {
    const findings = auditDesigns(
      [adr("0001", "Accepted"), adr("0002", "Proposed", "other")],
      [row("0001", "accepted", "monk-eee"), row("0002", "proposed", null, "other")],
    );
    expect(findings).toEqual([]);
  });

  it("flags an ADR that was never registered", () => {
    const findings = auditDesigns([adr("0048", "Proposed")], []);
    expect(kinds(findings)).toEqual(["unregistered"]);
    expect(findings[0].adr).toBe("0048");
  });

  it("flags a ledger row whose ADR is not present here", () => {
    const findings = auditDesigns([], [row("0036", "accepted", "monk-eee")]);
    expect(kinds(findings)).toEqual(["orphan"]);
  });

  it("flags a file and ledger that disagree about status", () => {
    const findings = auditDesigns(
      [adr("0020", "Accepted")],
      [row("0020", "proposed", null)],
    );
    expect(kinds(findings)).toEqual(["disagreement"]);
    expect(findings[0].detail).toMatch(/file says Accepted, ledger says proposed/);
  });

  // The ADR-0047 shape: reconcile_designs imports the status out of the file,
  // so a row can be `accepted` with nobody named as the decider. accept_design
  // then refuses it, because deciding again is not an undo — so this state is
  // stuck until someone reopens it, and it is invisible without this check.
  it("flags a decision that names no decider", () => {
    const findings = auditDesigns(
      [adr("0001", "Accepted")],
      [row("0001", "accepted", null)],
    );
    expect(kinds(findings)).toEqual(["undecided"]);
    expect(findings[0].detail).toMatch(/reopen_undecided_design/);
  });

  it("does not expect a decider on a proposed row", () => {
    const findings = auditDesigns([adr("0001", "Proposed")], [row("0001", "proposed", null)]);
    expect(findings).toEqual([]);
  });

  // "Superseded by X" is a different statement from a stale one. The ledger has
  // no such status, so neither side is wrong and forcing agreement would throw
  // information away. It is reported, but it is not drift.
  it("reports a superseded file as a modelling gap rather than drift", () => {
    const findings = auditDesigns(
      [adr("0018", "Superseded by [ADR-0032](0032-x.md)")],
      [row("0018", "accepted", "monk-eee")],
    );
    expect(kinds(findings)).toEqual(["unrepresentable"]);
    expect(findings.filter(isDrift)).toEqual([]);
  });

  it("separates drift from notes", () => {
    const findings = auditDesigns(
      [adr("0018", "Superseded by [ADR-0032](0032-x.md)"), adr("0048", "Proposed", "new")],
      [row("0018", "accepted", "monk-eee")],
    );
    expect(findings).toHaveLength(2);
    expect(kinds(findings.filter(isDrift))).toEqual(["unregistered"]);
  });
});
